using System;using System.IO;using System.Collections.Generic;using System.Threading;using ThinkPadModesV3;
internal static class DirectRpmSession {
 internal static bool Valid(int before,int after,int[] high1,int[] low,int[] high2,out int rpm){rpm=-1;if(before!=after||(before!=0&&before!=1&&before!=7&&before!=128)||high1.Length!=3||low.Length!=3||high2.Length!=3)return false;int min=65536,max=-1;for(int n=0;n<3;n++){if(high1[n]!=high2[n])return false;int r=low[n]|(high2[n]<<8);if(r!=0&&(r<500||r>6000))return false;min=Math.Min(min,r);max=Math.Max(max,r);}if(max-min>200||(min==0&&max!=0))return false;rpm=min+(max-min)/2;return true;}
 internal static bool Bank(LenovoOemTransport ec,bool bank,out int rpm,out int mode){rpm=-1;mode=-1;ec.SelectOem(bank);int before=ec.Read(0x2F);var a=new int[3];var b=new int[3];var c=new int[3];for(int n=0;n<3;n++){a[n]=ec.Read(0x85);b[n]=ec.Read(0x84);c[n]=ec.Read(0x85);}int after=ec.Read(0x2F);mode=after;return Valid(before,after,a,b,c,out rpm);}
 internal static int Run(string folder,string name,string parent){Environment.SetEnvironmentVariable("TPM_LAB_GUARD_NAME",name);Environment.SetEnvironmentVariable("TPM_LAB_GUARD_PID",parent);long begin=CoolingPaths.Tick,lastGood=begin;int rejected=0,frames=0;string error=null;try{using(var session=new ZeroCalibrationSession()){while(true){session.Pulse();int a=-1,b=-1,ma=-1,mb=-1;bool valid=false;using(var ec=new LenovoOemTransport(false)){try{valid=Bank(ec,false,out a,out ma)&&Bank(ec,true,out b,out mb)&&ma==mb;if(ec.ModeWrites!=0)throw new IOException("RPM reader wrote fan mode");}finally{ec.SelectOem(false);}}if(valid){lastGood=CoolingPaths.Tick;frames++;session.Sample(new Dictionary<string,object>{{"Mode",ma},{"Fan1",a},{"Fan2",b}});}else rejected++;if(CoolingPaths.Tick-lastGood>4500)throw new IOException("Aucune double lecture RPM cohérente depuis4.5s");Atomic.Write(Path.Combine(folder,"direct-rpm.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Frames=frames,Rejected=rejected,AgeMs=CoolingPaths.Tick-lastGood,Fan1=valid?(int?)a:null,Fan2=valid?(int?)b:null,Mode=valid?(int?)ma:null}));Thread.Sleep(valid?250:40);}}}catch(Exception e){error=e.Message;Atomic.Write(Path.Combine(folder,"direct-rpm-result.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Frames=frames,Rejected=rejected,Error=error}));return 1;}}
 internal static int Verify(){int r;int[] high={9,9,9},low={196,196,196},zero={0,0,0};if(!Valid(128,128,high,low,high,out r)||r!=2500)return 1;if(!Valid(0,0,zero,zero,zero,out r)||r!=0)return 2;if(Valid(0,128,zero,zero,zero,out r))return 3;if(Valid(0,0,high,low,zero,out r))return 4;if(Valid(128,128,new[]{48,48,48},zero,new[]{48,48,48},out r))return 5;if(Valid(128,128,zero,new[]{0,40,0},zero,out r))return 6;if(Valid(128,128,high,new[]{0,255,0},high,out r))return 7;return 0;}
}
